#include "dsky_hours_output_check.h"
#include "dsky_hours_output_vectors.h"
uint16_t dsky_hours_output_checkpoint(uint16_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;uint16_t f,p,end,failures=0;if(n>=DSKY_HOURS_OUTPUT_FROZEN_COUNT)return 1;dsky_hours_output_input(s,&io,dsky_hours_output_numbers[n],&mission);p=dsky_hours_output_before_offsets[n];end=dsky_hours_output_before_offsets[n+1u];while(p<end){uint16_t at=dsky_hours_output_before_patch[p][0],value=dsky_hours_output_before_patch[p++][1];if(at<2048u)s->words[at]=value;else if(at==2048u)io.superbank=value;else if(at==2049u)io.interrupt_enabled=value;else return 1;}*before=*s;old=io;if(dsky_hours_output(s,&io,mission,(enum dsky_hours_stage)dsky_hours_output_stages[n])!=P66_BIAS_OK)++failures;p=dsky_hours_output_after_offsets[n];end=dsky_hours_output_after_offsets[n+1u];for(f=0;f<2050u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:old.interrupt_enabled;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:io.interrupt_enabled;if(p<end&&dsky_hours_output_after_patch[p][0]==f)expected=dsky_hours_output_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
